/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.8 Confirm shipments
/// </summary>
internal final class METSalesOrderShipmentConfirm
{
    FormDataSource shipmentFormDataSource;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_shipmentFormDataSource"><c>METShipmentTable</c> form data source</param>
protected void new(FormDataSource _shipmentFormDataSource)
{
    shipmentFormDataSource = _shipmentFormDataSource;
}

/// <summary>
/// Construct method
/// </summary>
/// <param name = "_shipmentFormDataSource"><c>METShipmentTable</c> form data source</param>
/// <returns><c>METSalesOrderShipmentConfirm</c> class instance</returns>
static METSalesOrderShipmentConfirm construct(FormDataSource _shipmentFormDataSource)
{
    return new METSalesOrderShipmentConfirm(_shipmentFormDataSource);
}

    /// <summary>
    /// Run method to validate and update shipment status
    /// </summary>
    /// <returns>True if method updated shipments; otherwise, false</returns>
    boolean run()
    {
        #OCCRetryCount
        boolean executed = false;

        try
        {
            ttsbegin;
            
            // validate
            if (this.validate())
            {
                // update selected shipment records status to loaded
                this.updateShipmentStatus();
                executed = true;
            }

            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }

        return executed;
    }

    /// <summary>
    /// Method to update shipment status to Loaded for selected shipments
    /// </summary>
    void updateShipmentStatus()
    {
        MultiSelectionHelper    selection;
        METShipmentTable        shipmentTable;

        selection = MultiSelectionHelper::construct();
        selection.parmDatasource(shipmentFormDataSource);
        shipmentTable = selection.getFirst();

        // loop through selected shipment
        while (shipmentTable)
        {
            // update status to loaded
            shipmentTable.selectForUpdate(true);
            shipmentTable.ShipmentStatus = WHSShipmentStatus::Loaded;
            shipmentTable.update();

            shipmentTable = selection.getNext();
        }
    }

    /// <summary>
    /// Validate method to check if any missing informations and ask user to proceed or not
    /// </summary>
    /// <returns>True if validated and ready to proceed to confirmation; otherwise, false</returns>
    [SuppressBPWarning('BPUnusedStrFmtArgument', 'BP bug')]
    boolean validate()
    {
        MultiSelectionHelper    selection;
        METShipmentTable        shipmentTable;
        boolean                 ret = true;
        boolean                 validateDangerousGoods = true, validateContainer = true, validateCarrierSeal = true;
        METCustParameters       metCustParameters = METCustParameters::Find();
        str                     warningMessage;
        const str emptyString = '';

        selection = MultiSelectionHelper::construct();
        selection.parmDatasource(shipmentFormDataSource);
        shipmentTable = selection.getFirst();

        // loop through selected shipment
        while (shipmentTable)
        {
            // validate container
            if (validateContainer
            &&  !MetContainerTable::existShipmentId(shipmentTable.ShipmentId))
            {
                validateContainer = false;
            }

            // validate carrier seal
            if (validateCarrierSeal
            &&  !MetCarrierSealTable::existShipmentId(shipmentTable.ShipmentId))
            {
                validateCarrierSeal = false;
            }

            // validate multimodal dangerous goods
            if (validateDangerousGoods 
            &&  shipmentTable.custGroupId() == metCustParameters.MultimodalDGCustGroup 
            &&  !HMIMMultimodalDG::METExistShipmentId(shipmentTable.ShipmentId))
            {
                validateDangerousGoods = false;
            }

            shipmentTable = selection.getNext();
        }

        // create the warning message based on what is missing
        if (!validateContainer)
        {
            warningMessage += "@MET:container";
        }

        if (!validateCarrierSeal)
        {
            warningMessage += warningMessage == emptyString ? "@MET:carrierSeal" : "@MET:orCarrierSeal";
        }

        if (!validateDangerousGoods)
        {
            warningMessage += warningMessage == emptyString ? "@MET:multimodalDangerousGoods" : "@MET:orMultimodalDangerousGoods";
        }

        // if warning message
        if (warningMessage)
        {
            // Ask users if they want to proceed with confirmation
            ret = Box::okCancel(strFmt("@MET:SalesORderShipmentConfirmWarning", warningMessage), DialogButton::Cancel) == DialogButton::Ok;
        }

        return ret;
    }

    /// <summary>
    /// Main method
    /// </summary>
    /// <param name = "_args">Arguments</param>
    public static void main(Args _args)
    {
        FormDataSource  formDS;
        TableId         callerTableId;
        FormRun         callingFormRun;
        METIFormRefresh callingForm;
        boolean         executed;

        if (!_args.caller())
        {
            throw error("@SYS22539");
        }

        callingFormRun = _args.caller() as FormRun;

        if (_args && callingFormRun)
        {
            callerTableId = _args.dataset();
            switch (callerTableId)
            {
                case tableNum(METShipmentTable):
                    // get the caller datasource
                    formDS = FormDataUtil::getFormDataSource(_args.record());
                    break;
            }

            // Create class and run confirmation
            METSalesOrderShipmentConfirm soShipmentConfirm = METSalesOrderShipmentConfirm::construct(formDS);
            executed = soShipmentConfirm.run();

            // Refresh the sales order shipment to show all records updated to shipment status Loaded
            if (executed && callingFormRun != null && formHasMethod(callingFormRun, identifierStr(refresh)))
            {
                callingForm = callingFormRun as METIFormRefresh;
                callingForm.refresh();
            }

        }
    }
